        ("ما هو البيت الذي يُفتتح به الشعر العربي وتتساوى فيه قافيتا الشطرين؟", ["مَطْلَع القَصِيدَة (التَّصْرِيع)", "البَيْت الخِتَامِيّ", "بَيْت القَصِيد", "الحَشْو"], 0, "المطلع المصرع يشهد تماثل نغمة العروض والضرب في مفتتح القصيدة.", "الأدب والعروض"),
        ("ما هو البحر الشعري الأقصر وزناً وأسرع إيقاعاً في دوائر الخليل؟", ["بَحْر الرَّجَز", "البَحْر الطَّوِيل", "البَحْر البَسِيط", "البَحْر الكَامِل"], 0, "الرجز حمار الشعراء لخفته وسهولة النظم على تفاعيله (مستفعلن).", "العروض"),
        ("ما اسم الفن الأدبي النثري الذي يعتمد على الحوار المسرحي بين الشخصيات؟", ["المَسْرَحِيَّة", "المَقَالَة", "الرِّوَايَة التَّارِيخِيَّة", "الشِّعْر المَلْحَمِيّ"], 0, "المسرحية تعتمد على تمثيل الصراع وتتابع الأحداث عبر الحوار المباشر.", "الفنون النثرية"),
        ("ما الفن النثري الوجيز الذي ينقل تجربة إنسانية عميقة في جملة واحدة مكثفة؟", ["الحِكْمَة والمَثَل", "الرِّوَايَة", "الخُطْبَة المِنْبَرِيَّة", "المُنَاظَرَة"], 0, "الحكمة خلاصة نظر فاحص وتجربة صادقة تهدف لتوجيه السلوك البشري.", "الأدب"),
        ("ما معنى قول الخطيب: 'أَمَّا بَعْدُ' في مستهل خطبته؟", ["فَصْل الخِطَاب للانتقال للموضوع", "نهاية الحديث", "طلب الاستراحة", "التحية وحدها"], 0, "'أما بعد' عبارة اصطلاحية تفصل بين الديباجة والمقصود الرئيسي للخطاب.", "الخطابة والإنشاء"),
        ("ما نوع الجمع في كلمة 'مَصَابِيح'؟", ["صِيغَة مُنْتَهَى الجُمُوع (تَكْسِير)", "جَمْع مُذَكَّر سَالِم", "جَمْع مُؤَنَّث سَالِم", "اسْم جِنْس جَمْعِيّ"], 0, "كل جمع تكسير بعد ألف تكسيره حرفان أو ثلاثة أوسطها ساكن هو صيغة منتهى الجموع.", "الصرف"),
        ("ما إعراب الضمير 'نا' في: 'أَكْرَمَنَا الأُسْتَاذُ'؟", ["ضمير متصل في محل نصب مفعول به", "في محل رفع فاعل", "في محل جر مضاف إليه", "مبتدأ"], 0, "الأستاذ هو الفاعل المعطي للإكرام، والضمير 'نا' وقع عليه الإكرام فهو مفعول به.", "قواعد النحو"),
        ("ما نوع 'لا' في جملة: 'لا شَيْءَ أَغْلَى مِنَ الوَطَنِ'؟", ["لا النَّافِيَة لِلْجِنْس", "لا النَّاهِيَة", "لا العَاطِفَة", "لا الزَّائِدَة"], 0, "'لا' النافية للجنس تعمل عمل 'إنّ' فتنفي الخبر عن جنس اسمها استغراقاً.", "قواعد النحو"),
        ("ماذا نطلق على الكلمة التي لا تقبل التنوين وتُجر بالفتحة نيابة عن الكسرة؟", ["المَمْنُوع مِنَ الصَّرْف", "المَقْصُور", "المَنْقُوص", "المُعْتَلّ"], 0, "الممنوع من الصرف يُحرم من التنوين ويجر بالفتحة ما لم يُضف أو يُعرف بأل.", "قواعد النحو"),
        ("اختر الكلمة الممنوعة من الصرف لعلة العلمية ووزن الفعل:", ["أَحْمَد", "مُحَمَّد", "عَلِيّ", "خَالِد"], 0, "'أحمد' علم جاء على وزن الفعل 'أفعل' فهو ممنوع من الصرف لذلك.", "قواعد النحو"),
        ("ما نوع المنادى في جملة: 'يَا طَالِبَ العِلْمِ اجْتَهِدْ'؟", ["مُنَادَى مُضَاف مَنْصُوب", "شَبِيه بالمُضَاف", "نَكِرَة مَقْصُودَة", "عَلَم مُفْرَد"], 0, "طالب مضاف والعلم مضاف إليه، وحكم المنادى المضاف النصب بالفتحة.", "قواعد النحو"),
        ("ما معنى الاستعارة في علم البيان والبلاغة؟", ["تَشْبِيه حُذِفَ أَحَدُ طَرَفَيْهِ", "جَمْع بَيْنَ ضِدَّيْن", "تَكْرَار لَفْظِيّ", "حَذْف الكَلِمَة تَمَاماً"], 0, "الاستعارة مجاز لغوي أصله تشبيه بليغ حُذف مشبهه أو مشبهه به.", "البلاغة"),
        ("ما إعراب كلمة 'طَالِباً' في: 'حَضَرَ عِشْرُونَ طَالِباً'؟", ["تَمْيِيز مَنْصُوب", "مَفْعُول بِهِ", "حَال", "مُضَاف إِلَيْهِ"], 0, "الاسم المفرد النكرة الواقع بعد ألفاظ العقود يعرب تمييزاً منصوباً بالفتحة.", "قواعد النحو"),
        ("ما الحرف المصدري الذي ينصب الفعل المضارع مباشرة؟", ["أَنْ", "إِنْ الشَّرْطِيَّة", "قَدْ", "سَوْفَ"], 0, "'أنْ' حرف مصدري ونصب واستقبال يخلص المضارع للمستقبل وينصبه.", "قواعد النحو"),
