        ("ما إعراب كلمة 'سَرِيعاً' في: 'انْطَلَقَ القِطَارُ سَرِيعاً'؟", ["نَائِب عَنِ المَفْعُول المُطْلَق (أَوْ حَال)", "مَفْعُول فِيهِ", "مُبْتَدَأ", "مَفْعُول مَعَهُ"], 0, "'سريعاً' صفة للمصدر المحذوف أي انطلاقاً سريعاً فتنوب عنه أو تعرب حالاً.", "قواعد النحو"),
        ("ما نوع المشتق في كلمة 'مُسْتَشْفَى'؟", ["اسْم مَكَان", "اسْم فَاعِل", "اسْم آلَة", "صِفَة مُشَبَّهَة"], 0, "'مستشفى' يدل على مكان وقوع الاستشفاء والعلاج الطبي.", "الصرف"),
        ("ماذا نطلق على الاسم المنسوب في تركيب: 'اللُّغَةُ العَرَبِيَّةُ'؟", ["العَرَبِيَّة (لِحُوق يَاء النَّسَب المُشَدَّدَة)", "اللُّغَة", "النَّعْت فَقَط", "المُضَاف"], 0, "الاسم المنسوب تلحقه ياء مشددة مكسور ما قبلها للدلالة على النسبة.", "الصرف"),
