        # 76-100: نصوص، قراءة وتطبيقات لغوية شمولية
        ("ما المعنى المستفاد من النهي القرآني: 'وَلَا تُصَعِّرْ خَدَّكَ لِلنَّاسِ'؟", ["التَّحْذِير مِنَ التَّكَبُّر والاسْتِعْلَاء", "الأمر بالصمت", "النهي عن المشي", "الأمر بالحزن"], 0, "تصعير الخد هو إمالة الوجه كبراً وغروراً، والنهي يدعو للتواضع ومخالطة الناس بلين.", "التفسير والأدب"),
        ("ما دلالة اقتران الصدق بالأمانة في التراث الأخلاقي العربي؟", ["أَنَّهُمَا أَسَاس الثِّقَة وتَمَاسُك المُجْتَمَع", "أنهما يجلبان الشهرة فقط", "أنهما خاصان بالتجارة", "أنهما يسقطان بالنسيان"], 0, "الصدق في الحديث والأمانة في المعاملة يوطدان أواصر الأخوة وسلامة التعامل.", "الأخلاق والسلوك"),
