        ("كيف يُصاغ اسم التفضيل من الفعل الثلاثي المستوفي للشروط مثل 'فَضُلَ'؟", ["أَفْضَل (عَلَى وَزْن أَفْعَل)", "فَاضِل", "مَفْضُول", "فَضِيلَة"], 0, "يصاغ اسم التفضيل قياساً على وزن 'أفعل' للدلالة على اشتراك اثنين في صفة وزيادة أحدهما.", "الصرف"),
        ("ما حكم الاستماع الواعي لحديث الآخرين في آداب المجلس؟", ["أَدَب رَفِيع يَدُلّ عَلَى الاحْتِرَام والتَّرَبِّي", "مضيعة للوقت", "أمر لا فائدة منه", "مكروه اجتماعياً"], 0, "حسن الاستماع من شيم العقلاء ويتيح الفهم الدقيق قبل التعقيب والرد.", "الآداب والتواصل"),
        ("ما الغرض الحقيقي من دراسة مادة اللغة العربية في المرحلة الثانوية؟", ["إِتْقَان القِرَاءَة والكِتَابَة والتَّوَاصُل الفَصِيح", "حفظ الكلمات بلا فهم", "اجتياز الوقت", "التحدث بلهجات عامية فقط"], 0, "الهدف تنمية الذائقة اللغوية والقدرة التحليلية والتعبير السليم شفهياً وكتابياً.", "أهداف التعلم"),
        ("ما هي الطريقة الفضلى لمراجعة القواعد النحوية قبيل الامتحان النهائي؟", ["حَلّ التَّطْبِيقَات النَّمُوذَجِيَّة والإِعْرَاب العَمَلِيّ", "حفظ التعاريف دون تدريب", "إهمال التمارين", "قراءة العناوين فقط"], 0, "الممارسة التطبيقية وإعراب الجمل المتنوعة يرسخان القواعد الذهنية ويضمنان الامتياز.", "المنهجية الدراسية"),
        ("ما الكلمة التي تمثل جمعاً سالماً لمذكر ينتهي بياء ونون في حالة النصب؟", ["المُعَلِّمِينَ", "المعلمات", "المدارس", "الأقلام"], 0, "'المعلمين' جمع مذكر سالم ينصب ويجر بالياء الساكنة المفتوح ما قبلها.", "قواعد النحو"),
