        ("ماذا نطلق على الكلمات التي تتطابق في النطق وتختلف جذرياً في المعنى؟", ["الجِنَاس التَّامّ", "الطباق", "المقابلة", "الترادف"], 0, "الجناس التام اتفاق اللفظين في نوع الحروف وحركاتها وعددها وترتيبها مع اختلاف المعنى كـ صليت المغرب في المغرب.", "البلاغة"),
        ("ما الفعل الماضي المجرد من بين الأفعال الآتية؟", ["نَصَرَ", "انْتَصَرَ", "اسْتَنْصَرَ", "تَنَاصَرَ"], 0, "'نصر' فعل ماض ثلاثي مجرد خلت حروفه من حروف الزيادة الصرفية.", "الصرف"),
